      SUBROUTINE DECPLOT(FLAG,INAMS)      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'ICODE.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'IOFLAG.CIN'      INCLUDE 'KNAME.CIN'      INCLUDE 'LNAME.CIN'      INCLUDE 'PARDAT.CIN'      INCLUDE 'PARVAL.CIN'      INCLUDE 'RDBUFF.CIN'      INCLUDE 'RDWRDS.CIN'      CHARACTER*15 KPARA      LOGICAL      FLAGC      FLAG = .FALSE.C      IPARM = 0      CALL FNDNAM(KNAME,LNAME,INAME)      IF (INAME .NE. 0) THEN        PDATA(INAMS) = FLOAT(ICODE)        IPTYP(INAMS) = 1        PDATA(INAMS+1) = FLOAT(JCODE)        IPTYP(INAMS+1) = 1        INAMS = INAMS + 2        IPARM = 3        GO TO 100      ENDIFC      CALL FNDLAB(KNAME,NELMN)      IF (NELMN .EQ. 0) THEN        CALL RDFAIL        WRITE (NOUT,920) KNAME(1:LNAME)        FLAG = .TRUE.        GO TO 100      ENDIF      IF (ITEM .EQ. '[') THEN        CALL RDNEXT        IF (ENDFIL) GO TO 100        CALL RDWORD(KPARA,LPARA)        IF (LPARA .EQ. 0) THEN          CALL RDFAIL          WRITE (NOUT,930)          GO TO 100        ENDIF        CALL RDNEXT        IF (ENDFIL) GO TO 100        CALL RDTEST(']',FLAG)        IF (FLAG) GO TO 100        NTYPE1 = NTYPE        IST = ISTOR(NELMN)        NTYPE = IDATA(IST)        CALL RDPARS(KPARA,LPARA,IEP)        IF (IEP .EQ. 0) THEN          CALL RDFAIL          WRITE (NOUT,940) KNAME(1:LNAME), KPARA(1:LPARA)          FLAG = .TRUE.          GO TO 100        ENDIF        CALL SKETCH(NELMN)        PDATA(INAMS+1) = IST + IPTOJ(IEP)        NTYPE = NTYPE1      ELSE        PDATA(INAMS+1) = ISTOR(NELMN) + 1      ENDIF      PDATA(INAMS) = 9.0      IPTYP(INAMS) = 1      IPTYP(INAMS+1) = 1      INAMS = INAMS + 2      IF (ENDFIL) GO TO 100C  100 RETURNC-----------------------------------------------------------------------  920 FORMAT(' *** ERROR *** UNKNOWN PARAMETER KEYWORD "',A,'"'/' ')  930 FORMAT(' *** ERROR *** MULTIPLE DEFINITION OF PARAMETER "',A,     +       '"'/' ')  940 FORMAT (' *** ERROR *** UNKNOWN ELEMENT PARAMETER "',A,'[',A,']"'/     +       ' ')C-----------------------------------------------------------------------      END